"""Run the Phase 4 scenarios and write docs/14-phase4-evidence.md from real outputs. MUT_OUT=<file> embeds an existing mutation sweep."""
import hashlib, io, json, os, pathlib, subprocess, sys, time, warnings, contextlib
ROOT = pathlib.Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "src")); sys.path.insert(0, str(ROOT / "tests")); warnings.simplefilter("ignore")
from rig4 import *
from halvard import cli
from halvard.courier import analysis, exercises
from halvard.courier.analysis import AttachmentAnalyzer, LinkAnalyzer, Intel, ReferenceWeb
from halvard.courier.auth import DomainAuthMonitor, ReferenceDNS
from halvard.relay.actions import ActionRequest

AN, SD = Principal("u-an", "analyst"), Principal("u-sd", "service_desk")
out = []
H = lambda t: out.append(f"\n## {t}\n"); P = lambda t="": out.append(t)
def code(t): out.append("```\n" + str(t).rstrip() + "\n```")
env = dict(os.environ, PYTHONWARNINGS="ignore")
P("# Phase 4 evidence\n")
P(f"Generated by `tools/run_acceptance_p4.py` on {time.strftime('%Y-%m-%d %H:%M UTC', time.gmtime())}. Every output is from that run. "
  "The mail platform and the web are **reference models written by the same author as the analysers**. Attachment analysis is **static only**; nothing is executed. Read **Not demonstrated**.")
t = subprocess.run([sys.executable, "-W", "ignore", "-m", "unittest", "discover", "-s", "tests"], cwd=ROOT, capture_output=True, text=True, env=env)
H("Test suite"); code("\n".join(t.stderr.strip().splitlines()[-4:]))
mo = os.environ.get("MUT_OUT"); mtxt = pathlib.Path(mo).read_text(encoding="utf-8") if mo and pathlib.Path(mo).exists() else subprocess.run([sys.executable, "tools/mutation_check.py"], cwd=ROOT, capture_output=True, text=True, env=env).stdout
H("Do the tests bite? (full sweep on throwaway copies)"); code(mtxt); P(f"Killed: {mtxt.count('KILLED')}; survived or skipped: {mtxt.count('SURVIVED') + mtxt.count('SKIP')}.")

H("D1. A malicious mailed attachment and the device that opened it appear as one case (acceptance)")
buf = io.StringIO()
with contextlib.redirect_stdout(buf): cli.mailed_attachment()
code(buf.getvalue())
P("The attachment is deliberately clean to static analysis, so the first verdict is 'allow'. It is caught later by intelligence, and the laptop is found by hunting telemetry for the file's fingerprint. "
  "That is the delayed-verdict case, which is where a post-delivery design is weakest and where the endpoint evidence matters.")

H("D2. Analysers: what they flag and what they leave alone")
A = AttachmentAnalyzer(Intel()); rows = []
for name, data in (("invoice.docm (macro + downloader strings)", macro_doc()), ("minutes.docx (ordinary)", docx_like()), ("invoice.pdf.exe", b"MZ" + b"\0" * 60), ("scan.iso", b"CD001" + b"x" * 40), ("EICAR test string", analysis.EICAR)):
    v = A.analyze(name.split(" ")[0] if "." in name.split(" ")[0] else "f.bin", data); rows.append(f"{name:42} -> {v.decision:10} {v.score:.2f}  {'; '.join(v.reasons)[:90]}")
web = ReferenceWeb({"http://bit.ly/x1": {"redirect": "http://login-m1crosoft.example/a"}, "http://login-m1crosoft.example/a": {"html": '<h1>Microsoft</h1><input type="password">'}, "https://acme.com/wiki": {"html": "docs"}})
L = LinkAnalyzer(Intel(), web, {"acme.com"})
for text, href in (("Open your document", "http://bit.ly/x1"), ("wiki", "https://acme.com/wiki"), ("https://acme.com/payroll", "http://evil.example/p")):
    v = L.analyze(text, href); rows.append(f"link {href:36} -> {v.decision:10} {v.score:.2f}  {'; '.join(v.reasons)[:90]}")
code("\n".join(rows)); P("Weights and thresholds are hand-set. No detection or false-positive rate is claimed.")

H("D3. Impersonation and payment fraud")
w = World4(); cases = [("lookalike supplier, new bank details", dict(sender="ar@g1obex-supplies.com", subject="Invoice overdue - urgent payment", body=f"Our bank details changed. Pay {ROGUE_IBAN} today.", display_name="Globex Accounts", reply_to="ar@mail-pay.example")),
    ("genuine supplier domain, different bank account", dict(sender="ar@globex-supplies.com", subject="Updated bank details", body=f"New bank account for payments: {ROGUE_IBAN}", display_name="Globex AR")),
    ("genuine supplier, usual account (quiet)", dict(sender="ar@globex-supplies.com", subject="Invoice", body=f"Invoice attached. IBAN {SUPPLIER_IBAN}", display_name="Globex AR")),
    ("'Maria Lopez' from a webmail address, gift cards", dict(sender="m.lopez@gmail.example", subject="Quick favour", body="Buy gift cards today and do not tell anyone.", display_name="Maria Lopez", reply_to="x@proton.example")),
    ("colleague (quiet)", dict(sender="maria@acme.com", subject="Lunch?", body="Noon?", display_name="Maria Lopez"))]
rows = []
for label, kw in cases:
    n0 = len(w.cp.courier.findings); w.send(**kw); fs = w.cp.courier.poll()
    rows.append(f"{label:52} -> " + ("; ".join(f"{f.detector} {f.confidence:.2f}" for f in fs) or "no finding"))
code("\n".join(rows))

H("D4. Mailbox rules and forwarding after a stolen session merge with the takeover case")
w = World4().alice_signs_in(); w.stealer_runs(); w.attacker_replays(); m = w.cp.mail
m.set_forwarding("alice@acme.com", "collector@evil.example", actor="alice@acme.com", ip="203.0.113.7")
m.add_rule("alice@acme.com", {"subject_contains": ["invoice", "payment"]}, {"mark_read": True, "move_to": "RSS Feeds"}, actor="alice@acme.com", ip="203.0.113.7")
w.cp.process(); c = next(iter(w.cp.cases.cases.values()))
L = [f"cases: {len(w.cp.cases.cases)}; sources: {sorted({f.source for f in c.findings})}; confidence {w.cp.cases.confidence(c)[0]}", "mail findings: " + "; ".join(f"{f.details['detector']} {f.confidence:.2f}" for f in c.findings if f.source == "courier"),
     f"after containment: forwarding={m.mailboxes['alice@acme.com'].forwarding}; active rules={len(m.active_rules('alice@acme.com'))}; case {c.status}"]
w.send("customer@client.example", "Invoice payment", "Please confirm", to=("alice@acme.com",)); L.append(f"copies sent out after containment: {len([e for e in m.log if e['kind'] == 'auto_forward'])}")
code("\n".join(L))

H("D5. Service-desk release path")
w = World4(); mm = w.send("hr@partner.example", "Holiday calendar", "see attached"); w.cp.process(); w.cp.engine.request(ActionRequest("clawback_message", AN, [mm.id], "precaution", None, {})); L = []
L.append("desk view: " + str(w.cp.courier.quarantined_for("alice@acme.com")[0]))
r = w.cp.engine.request(ActionRequest("release_message", SD, [f"alice@acme.com|{mm.id}"], "x", None, {})); L.append(f"release with no reason: {r.status} - {r.message}")
r = w.cp.engine.request(ActionRequest("release_message", SD, [f"alice@acme.com|{mm.id}"], "user expects it", None, {"reason_text": "user expects it"})); L.append(f"low-risk release by the desk: {r.status}")
bad = w.send("billing@vendor-docs.example", "Invoice", "x", attachments=[("i.docm", macro_doc())]); w.cp.process()
r = w.cp.engine.request(ActionRequest("release_message", SD, [f"alice@acme.com|{bad.id}"], "user insists", None, {"reason_text": "user insists"})); L.append(f"release of a harmful message by the desk: {r.status} ({r.requirement.level}); desk approving own request: {w.cp.engine.approve(r.action_id, SD).status}")
L.append(f"analyst approves: {w.cp.engine.approve(r.action_id, AN).status}")
code("\n".join(L))

H("D6. Sender authentication posture")
dns = ReferenceDNS({"acme.com": ["v=spf1 include:_spf.mail.example ~all"], "_spf.mail.example": ["v=spf1 ip4:203.0.113.0/24 ~all"], "_dmarc.acme.com": ["v=DMARC1; p=none"], "open.example": ["v=spf1 +all"]})
M = DomainAuthMonitor(["acme.com", "open.example", "nospf.example"], dns)
for i in range(30): M.ingest(Message(f"m{i}", 0, "a@acme.com", "A", "s", "b", ["x@y"]))
M.ingest(Message("bad", 0, "ceo@acme.com", "CEO", "s", "b", ["x@y"], auth={"spf": "fail", "dkim": "none", "dmarc": "fail"}))
code("\n".join(f"[{f.severity}] {f.summary}\n        -> {f.action}" for f in M.posture(dkim_selectors=["s1"])) + f"\nspoofing attempts against acme.com seen: {len(M.spoof_attempts)}")

H("D7. Practice exercise from a real incident, and its privacy rule")
ex = exercises.build_from_finding("bank_details_changed", "Finance"); L = [f"subject: {ex.subject}", f"body: {ex.body}", "clues: " + "; ".join(ex.clues), f"right action: {ex.right_action}"]
for i in range(4): exercises.answer(ex, f"p{i}", 2, True)
L.append("department result with 4 answers: " + exercises.department_summary(ex)["message"]); exercises.answer(ex, "p4", 3, True); L.append("with 5 answers: " + str(exercises.department_summary(ex)))
code("\n".join(L))

H("Not demonstrated (so not claimed)")
for x in ("Dynamic detonation. Attachment verdicts are static analysis plus reputation; links are followed only in an offline model of the web. A document that is clean to static analysis passes until intelligence or the endpoint catches it (D1 depends on exactly that).",
          "A real Microsoft 365 or Google Workspace connector, its credentials and rate limits, and mail-flow rules in a real tenant. The reference platform defines the contract.",
          "Inline (pre-delivery) blocking. Courier acts after delivery; the measured gap in D1 is 6.5 minutes by construction of the scenario, not a measured production figure.",
          "Impersonation and phishing detection quality on real mail. Weights are hand-set; there is no measured detection or false-positive rate.",
          "F067 (file-sharing and third-party apps in collaboration suites), chat platforms, per-recipient behaviour baselines, a polling scheduler, and automatic expiry of pushed block-list hashes.",
          "Everything in the earlier phases' 'Not demonstrated' lists still applies (no native Windows/macOS sensor, no console, no asymmetric signing, no pen test).")  :
    P("- " + x)
(ROOT / "docs" / "14-phase4-evidence.md").write_text("\n".join(out) + "\n", encoding="utf-8"); print("wrote docs/14-phase4-evidence.md; suite:", "OK" if t.returncode == 0 else "FAILED")
